static u8        g_lvl_segment;
static u8 g_terr_sec;        /* active terrain section */
static u8 g_terr_target;     /* target section during a switch */
static u16 g_terr_up_idx;    /* next slot for the staged upload */

/* Select the active terrain section. g_lvl_tile_used/remap then point at
   that section's tables; the tile data itself is loaded by build_lvl1()
   or, during a running switch, by terr_sec_step(). */
/* FORWARD DECLARATIONS - C89, NOT cosmetics. A call with no prototype in
   scope makes the compiler assume a return type of int, and it then works on
   the full HL instead of just L. The upper half still holds whatever the
   previous call left there, so a later "== 1" compiles to CP HL,1 and can
   silently fail. Compile with -w3 to see them: THC1-Warning-521 "Undefined
   return type" plus Warning-565 "class mismatch" (implicitly extern here,
   static at the definition). None of these four was actually broken - three
   are void or u16 (which happens to match int) and sspr_anim_find's u8 result
   is assigned straight into a u8 everywhere - but nothing kept it that way. */
static void tile_words_build(void);
static u16  reward_icon_for(u8 kind, u16 value);
static u8   sspr_anim_find(u16 n);
static void intro_load_pals(void);

static void lvl1_select_section(u8 sec) {
    if (sec >= (u8)LVL1_TERR_SEC_COUNT) sec = (u8)(LVL1_TERR_SEC_COUNT - 1u);
    g_terr_sec            = sec;
    /* This used to set only g_terr_sec. If g_terr_target still pointed at
       another section - after the boss it points at 3 - then
       terr_sec_step() saw an open switch on the next frame and loaded that
       section's tiles over the freshly built section 0: torn terrain
       exactly where the tile sets differ. respawn_do() worked around it
       with its own "g_terr_target = sec"; game_start() did not, so a
       normal restart after game over hit the same bug. */
    g_terr_target         = sec;
    g_terr_up_idx         = 0u;
    g_lvl_segment         = sec;   /* legacy: 0 = first section */
    g_lvl_tile_used       = lvl1_terr_used[sec];
    g_lvl_tile_remap      = lvl1_terr_remap[sec];
    g_lvl_tile_used_count = (u16)LVL1_TERR_ZONE;
    /* The precomputed tilemap words depend on g_lvl_tile_remap - rebuild
       them here. Three times per level instead of twenty times per
       incoming tile row. */
    tile_words_build();   /* declared above - see the C89 note there */
}

static void lvl1_select_segment(u8 segment) {
    /* Backwards-compatible wrapper: 0 = first section, 1 = the section the
       shop lives in. New code calls lvl1_select_section(). */
    lvl1_select_section(segment ? 1u : 0u);
}


/* The bar shift chunk 4 (bar_shift_vram_init) is fixed to the end of the
   ORIGINAL terrain zone (254-354, 101 slots). That boundary stays
   UNCHANGED regardless of how many slots a segment actually needs. Not to
   be confused with LVL1_TILE_USED_COUNT_A/B. */
#define LVL1_FIXED_ZONE_COUNT 101u

/* Terrain VRAM is NOT one contiguous block any more: the section budget
   needs more room than the old block 254-354 (101 slots) provides. Extra
   slots come from reclaimed font memory (69-127, see font_compact_init)
   and small free gaps - addressed through an indirection table rather than
   a single base value, exactly like the sprite pool. Order is arbitrary;
   254-354 survives as one chunk so that bar_shift_vram_init(), which hangs
   off its end, stays untouched. */
/* The small towers and the six anemones raise the bottleneck window to 185
   tiles. Covered from two sources: the last free VRAM tiles go to the
   zone, and the 254 block runs up to 337 (the sprite pool starts at 338).
   The remaining six come from a documented reserve: the three tentacle
   animations play frame 4 as a REPEAT of frame 2 (sequence 1,2,3,2 - it
   reads as four), so those strips need no slot of their own. */
/* The bottleneck window is 183 tiles; below that
   tools/plan_terrain_sections.mjs reports "impossible". The six extra
   addresses come from the sprite pool, whose 254 continuation now starts
   at 342 instead of 336.     NOTE: this only worked WITHOUT the boss -
   with it the pool needs 324 tiles,    without it 314, and 314 + 183 = 497
   is exactly what remains of the 512 tiles    beside the HUD bar (14) and
   the blank tile (1). Zero reserve. That was a    comparison build, not
   the answer; the answer is the section-wise sprite    loading, which
   keeps only what a section actually needs resident. */
#define LVL1_ZONE_MAX 189u
static u16 g_lvl_vram[LVL1_ZONE_MAX];

static void lvl1_vram_init(void) {
    u16 i = 0u, t;
    for (t = 38u;  t <= 68u  && i < LVL1_ZONE_MAX; t++) g_lvl_vram[i++] = t;   /* former font area plus the last free tiles */
    for (t = 69u;  t <= 127u && i < LVL1_ZONE_MAX; t++) g_lvl_vram[i++] = t;   /* reclaimed font area */
    for (t = 144u; t <= 147u && i < LVL1_ZONE_MAX; t++) g_lvl_vram[i++] = t;
    for (t = 253u; t <= 253u && i < LVL1_ZONE_MAX; t++) g_lvl_vram[i++] = t;
    for (t = 254u; t <= 347u && i < LVL1_ZONE_MAX; t++) g_lvl_vram[i++] = t;   /* bis 347 (Zone 189), Sprite-Pool ab 348 */
}



/* ---- Running section switch ----    A switch changes 30-60 tiles = up to
   1 KB of VRAM. Done in a single frame that    tears the picture (writes
   during active display are the cause of the    green/white sprite class
   of bug). Therefore: write only at the END of a frame,    at most
   TERR_UP_PER_FRAME slots per frame, and swap the table pointers only
   AFTER the last slot. The old section stays active throughout the
   transition.    That is safe because inside its lead window (40 rows
   back, 34 ahead) every    tile currently being streamed or drawn exists
   in BOTH sections - and, thanks    to the carry-forward assignment, at
   the same offset. */
#define TERR_UP_PER_FRAME 6u
#define TERR_SEC_LEAD 8u

static void terr_sec_begin(u8 target) {
    if (target == g_terr_sec || target >= (u8)LVL1_TERR_SEC_COUNT) return;
    g_terr_target = target;
    g_terr_up_idx = 0u;
}

/* Call at the end of the frame. Returns 1 while a switch is running. */
static u8 terr_sec_step(void) {
    volatile u16 *dst;
    const u16 *src;
    u16 n = 0u, w, j, raw;
    if (g_terr_target == g_terr_sec) return 0u;
    while (g_terr_up_idx < (u16)LVL1_TERR_ZONE && n < (u16)TERR_UP_PER_FRAME) {
        j   = g_terr_up_idx++;
        raw = lvl1_terr_used[g_terr_target][j];
        /* Slot unchanged? Then upload nothing - that is the whole point of
           the carry-forward assignment (typically 80-100 of 140 stay put). */
        if (raw == lvl1_terr_used[g_terr_sec][j]) continue;
        dst = (volatile u16*)0xA000u + (u16)g_lvl_vram[j] * 8u;
        src = &lvl_tile_data[raw][0];
        for (w = 0u; w < 8u; w++) dst[w] = src[w];
        n++;
    }
    if (g_terr_up_idx >= (u16)LVL1_TERR_ZONE) {
        lvl1_select_section(g_terr_target);   /* only switch over now */
        return 0u;
    }
    return 1u;
}

/* Call on a row change to start the switch in good time. At 6 slots per
   frame and ~60 changed tiles the upload takes about 10 frames, while a
   tile row lasts about 24 - so TERR_SEC_LEAD 8 is generous. */
static void terr_sec_check(u16 row) {
    u8 nxt;
    if (g_terr_target != g_terr_sec) return;          /* already running */
    nxt = (u8)(g_terr_sec + 1u);
    if (nxt >= (u8)LVL1_TERR_SEC_COUNT) return;       /* last section */
    if (row + (u16)TERR_SEC_LEAD >= lvl1_terr_sec_row[nxt]) terr_sec_begin(nxt);
}
/* Palettes: SCR2 hardware slots 0,5-15 for terrain (12), slots 1-4 for the
   bar; SCR1 palettes 0-4 terrain, 15 stars */
#define STAR_PAL        15u

// --- Sprite slot allocation (OAM 0-63) --
#define SPR_SHIP       0    /* 0-5: ship metasprite, 3 cells x 2 (a plus optional b overlay) - FIXED */
/* !! THESE THREE BOUNDARIES BELONG TOGETHER and have to move with
   SHIP_CELLS. The ship occupies SHIP_CELLS*2 slots FIXED, because its chain
   interleaves a and b: a cell without a b overlay burns its slot anyway, or
   the chain breaks (for the pool objects the b overlays sit in a run of
   their own behind the a run, and there a cell without b costs nothing -
   see SPLIT CHAINS). For the ship it is therefore the CELL COUNT that
   counts, not the colours.
   04.08.2026: the ship shrank from 24x24 out of seven cells to 16x16 out of
   THREE (a pyramid, apex on a +4 fine offset - the tool's tab can do that
   since today). 7*2 = 14 fixed slots became 3*2 = 6.
   !! THE EIGHT SLOTS DO NOT REACH THE POOL BY THEMSELVES. OAM_POOL_BASE/SIZE
   and the bullet slots are fixed numbers; changing only SHIP_CELLS throws
   the whole gain away and measures zero afterwards. */
/* Shots use real multiplexing: several LOGICAL instances share FEWER
   physical OAM slots, drawn on alternating g_flicker phases (see
   draw_sprites). Phase 0 draws the even logical instances into the
   physical slots, phase 1 the odd ones - saving 2 slots. Ship and player
   shots keep their fixed slots; EVERYTHING else (enemies, metasprite
   enemies, digits, worms, map object shots, thrusters, weapon system,
   pickups) comes from one shared dynamic pool, see oam_pool_*() below. */
#define SPR_BULLET_0    6   /* 6-7: 2 physical slots for MAX_BULLETS=4 logical shots (slot i%2, phase i/2 - see draw_sprites) */
/* The beam gets NO fixed slots. It had some for a while, because it kept
   coming away empty in the dense band - but the cause was a different one:
   it demanded a CONTIGUOUS block (although it does not chain at all) and
   handed everything back when it could not get everything. Both are gone;
   since then it takes individual slots and takes what is there. Measured
   over the whole run, at least 19 of 50 are free and it needs 4 to 6.
   Fixed slots would therefore be permanently paid-for room against an
   emergency that no longer exists - the priority from the reservation
   block in draw_sprites() is enough (user decision 04.08.). */
#define BEAM_SLOTS_MAX  6u
#define BULLET_PHYS_SLOTS 2u

/* ===== Shared dynamic OAM pool, slots 16-63 (48 of them) =====
   Replaces every earlier fixed or borrowed slot range. A freelist stack
   rather    than a bitmask: the TLCS-900H cannot test 48 bits cheaply
   (32-bit operations    are expensive here), and a stack of u8 values is
   both cheaper and simpler.     PRINCIPLE: each instance remembers its own
   assigned slot (or its two slots for    an a+b overlay or a 2-cell
   metasprite) as a field of its own struct, not via a    fixed index. The
   "last tile" fastpath cache therefore lives in the instance    rather
   than in the physical slot.     Assignment happens on the first draw
   after spawn, and again every frame while    an active instance still has
   NO slot - so a freed slot is picked up    immediately, without any
   system having to claim priority: whoever draws first    takes it.
   Release happens as soon as an instance goes inactive or leaves the
   screen (y>=CLIP_Y); the slot returns to the pool at once and can go to
   another    waiting instance in the SAME frame, since all drawing blocks
   run one after the    other inside the same draw_sprites() call.     The
   ORDER of the drawing blocks therefore sets the priority when slots run
   short: enemies -> metasprite enemies -> worms -> map object shots ->
   thrusters    -> weapon system -> pickups -> digits (score_draw, called
   last). Slots already    assigned are NEVER evicted - only new requests
   see the ordering, so anything    already on screen stays stable until
   its own despawn. */
#define OAM_POOL_BASE  8u
#define OAM_POOL_SIZE 56u
#define OAM_NONE 0xFFu
static u8 g_oam_pool[OAM_POOL_SIZE];
static u8 g_oam_pool_n;   /* number free in the stack */
static u8 g_oam_is_free[64];   /* 1 = slot is in the freelist (O(1) double-free guard, see oam_pool_free) */

/* ===== Early-out in the drawing path =====    Measured in the boss arena,
   VBlanks per 30 frames: draw_sprites() costs 23.5,    of which only 9 are
   the metasprite enemies. The rest is 1-2 VBlanks each    across a dozen
   systems that have NOTHING to do - an inactive object still    costs its
   loop iteration and usually a function call. Individually at the    noise
   floor, together a quarter of the frame; which is exactly why bisecting
   never found a single culprit.     One busy flag per system:    - the
   system's *_update() sets it while any instance is active (it already
   walks the same array every frame, so this is free),    - the drawing
   path skips its system at busy==0 and clears the flag itself at      the
   END of its own pass.     CRUCIAL against ghost sprites: the flag is only
   cleared in THE pass that    releases the OAM slots, never earlier. The
   sequence is: last instance goes    inactive -> flag still set -> drawing
   path runs one final time and frees all    slots -> flag drops. Clearing
   it too early leaves sprites on screen; clearing    it too late only
   costs one frame. When in doubt, later. */
static u8 g_busy_bullets, g_busy_mobullets, g_busy_ebullets, g_busy_enemies;
static u8 g_busy_metas, g_busy_worms, g_busy_wworms, g_busy_pickups;
static u8 g_busy_wpbul, g_busy_wpent;
static u8 g_busy_wcrawl;   /* wall crawlers, see wcrawls_update/draw */

static void oam_pool_init(void) {
    u8 i;
    for (i = 0u; i < 64u; i++) g_oam_is_free[i] = 0u;
    for (i = 0u; i < OAM_POOL_SIZE; i++) {
        g_oam_pool[i] = (u8)(OAM_POOL_BASE + i);
        g_oam_is_free[(u8)(OAM_POOL_BASE + i)] = 1u;
    }
    g_oam_pool_n = OAM_POOL_SIZE;
}
/* how many slots are still free - for the all-or-nothing assignment of the
   wall crawlers (see wcrawls_draw). */
static u8 oam_pool_free_count(void) { return g_oam_pool_n; }
/* TESTED AND REJECTED: handing out the lowest free slot first instead of
   LIFO, to keep contiguous blocks available for chaining. Measured: chain
   bits stayed at 9 of 58 - NO effect. The reason is arithmetic, not
   fragmentation: with 58 visible sprites, 42 of the 48 pool slots are
   taken and only 6 are free, so an 8-slot block for a 4-cell metasprite is
   impossible whatever the order. A useful lever would have to RELIEVE the
   pool, not sort it. */
/* TWO further rebuilds here TESTED AND REJECTED, both exactly zero:
   "lowest free slot first" (which collides with the block search) and two-
   ended assignment (single slots from the top, blocks from the bottom).
   The measurement behind it: shortly after spawn 44 of 58 sprites in the
   boss scene carry a chain bit, after ~150 frames only 9 - the metasprites
   lose their contiguous blocks and then draw 8 single slots instead of one
   chain. But the assignment order is NOT the cause (both rebuilds left the
   9 unchanged); with 42 of 48 slots taken there is simply no room for an
   8-slot block. An effective lever would have to cut the NUMBER of
   simultaneous sprites, not their distribution. */
static u8 oam_pool_alloc(void) {
    u8 s;
    if (g_oam_pool_n == 0u) return OAM_NONE;
    g_oam_pool_n--;
    s = g_oam_pool[g_oam_pool_n];
    g_oam_is_free[s] = 0u;
    return s;
}
/* BLOCK ALLOCATOR for sprite chaining: a K2GE chain always refers to the
   PREVIOUS OAM entry, so a chained metasprite needs n CONSECUTIVE slots.
   Runs only on an instance's first draw, not per frame, so the O(48)
   search is harmless there. Returns the base slot or OAM_NONE; on OAM_NONE
   the drawing path falls back to single-slot assignment, so the graphics
   stay correct either way, just without the chaining saving. */
/* ============ Priority in the OAM pool ============ Order by user
   decision 04.08.: ship - shots - items - enemies - thruster The ship has
   fixed slots (SPR_SHIP) and does not appear here; everything else shares
   the pool. IMPLEMENTED AS A RESERVE, NOT AS AN ORDER IN THE CODE. Whoever
   asks later in the frame would otherwise be out of luck - but the drawing
   order also fixes the ORDER IN THE PICTURE (lower slot = further
   forward), and that must not change. Instead every class leaves a reserve
   standing for the more important ones: a lower-ranked class only gets
   something while more than its reserve is free. Shots may take the pool
   down to zero, the thruster only while there is plenty. The numbers are a
   compromise, not a measurement: large enough that a missing enemy does
   not lose out to the thruster, small enough that everything is drawn in a
   quiet level. Whoever changes them should run autoplay.py --oam before
   and after. */
#define OAM_PRIO_SHOT   0u   /* Spielerschuesse, Strahl, Waffenmodule */
#define OAM_PRIO_ITEM   1u   /* Pickups */
#define OAM_PRIO_ENEMY  2u   /* Gegner, ihre Schuesse, Wuermer, Kriecher */
#define OAM_PRIO_THRUST 3u   /* Triebwerksflammen */
static const u8 oam_prio_rest[4] = { 0u, 3u, 6u, 12u };

static u8 oam_pool_alloc_p(u8 prio) {
    if (g_oam_pool_n <= oam_prio_rest[prio]) return OAM_NONE;
    return oam_pool_alloc();
}

static u8 oam_pool_alloc_run(u8 n) {
    u8 base, k, i, j;
    if (n == 0u || n > (u8)OAM_POOL_SIZE) return OAM_NONE;
    for (base = (u8)OAM_POOL_BASE; (u8)(base + n) <= (u8)(OAM_POOL_BASE + OAM_POOL_SIZE); base++) {
        for (k = 0u; k < n; k++)
            if (!g_oam_is_free[(u8)(base + k)]) break;
        if (k < n) continue;
        for (k = 0u; k < n; k++) {
            u8 s = (u8)(base + k);
            g_oam_is_free[s] = 0u;
            for (i = 0u; i < g_oam_pool_n; i++) {
                if (g_oam_pool[i] == s) {
                    for (j = (u8)(i + 1u); j < g_oam_pool_n; j++) g_oam_pool[j - 1u] = g_oam_pool[j];
                    g_oam_pool_n--;
                    break;
                }
            }
        }
        return base;
    }
    return OAM_NONE;
}
/* Take ONE specific slot if it is free (1 = got it). For the a/b pair of a
   normal enemy: only if oam0+1 is free can the b overlay be chained, since
   a chain refers to the DIRECTLY preceding slot. Otherwise it falls back
   to an unchained slot - always correct, just without the saving. */
static u8 oam_pool_take(u8 slot) {
    u8 i, j;
    if (slot < (u8)OAM_POOL_BASE || slot >= (u8)(OAM_POOL_BASE + OAM_POOL_SIZE)) return 0u;
    if (!g_oam_is_free[slot]) return 0u;
    g_oam_is_free[slot] = 0u;
    for (i = 0u; i < g_oam_pool_n; i++) {
        if (g_oam_pool[i] == slot) {
            for (j = (u8)(i + 1u); j < g_oam_pool_n; j++) g_oam_pool[j - 1u] = g_oam_pool[j];
            g_oam_pool_n--;
            break;
        }
    }
    return 1u;
}
static void oam_pool_free(u8 slot) {
    u8 i;
    if (slot == OAM_NONE) return;
    /* GUARD: only slots from the pool may go back into the freelist.
       Static structures start at 0 rather than OAM_NONE=0xFF, so an
       instance that never spawned saw slot 0 as "taken" and freed it. But
       OAM 0 is the SHIP'S NOSE (fixed slots 0-15): the pool then handed it
       to shots and enemies, which drew their graphics there. This affects
       every struct with OAM fields, so it is caught centrally here rather
       than at each site. */
    if (slot < (u8)OAM_POOL_BASE || slot >= (u8)(OAM_POOL_BASE + OAM_POOL_SIZE)) return;
    /* Guard against a double free: a slot already in the freelist must NOT
       go in again - otherwise two alloc() calls hand out the same slot
       (two objects share it, giving ghosts) and at n==SIZE the write
       g_oam_pool[n++] goes past the end of the array. */
    /* The double-free guard used to be a linear 48-entry search on EVERY
       free(), which adds up in dense metasprite scenes where the pool is
       exhausted and alloc/free churns constantly. Now O(1) via a free flag
       per slot: same safety, no loop. */
    if (g_oam_is_free[slot]) return;
    g_oam_is_free[slot] = 1u;
    if (g_oam_pool_n < (u8)OAM_POOL_SIZE) g_oam_pool[g_oam_pool_n++] = slot;
    (void)i;
}
/* OAM SCRUB: on real hardware the UnsetSprite write of a dying enemy can
   be lost to the display race - the slot is logically free but the sprite
   stays visible until the pool happens to reuse it. NOT reproducible in
   the emulator (three complete ghost-hunt runs, zero hits; the emulator
   loses no writes). Remedy: switch off one free pool slot per frame as a
   precaution, walking the freelist, so a lost "off" heals within about 1.5
   s. Costs one OAM byte read-modify-write per frame. */
static u8 g_oam_scrub_i;
static void oam_scrub_step(void) {
    if (g_oam_pool_n == 0u) return;
    if (g_oam_scrub_i >= g_oam_pool_n) g_oam_scrub_i = 0u;
    UnsetSprite(g_oam_pool[g_oam_scrub_i]);
    g_oam_scrub_i++;
}
#define MAX_BULLETS  4
#define MAX_ENEMIES  10   /* a chain needs up to 8 at once (lvl_spawn_count) */
#define MAX_MAPOBJ_BULLETS 16   /* logical - every active instance pulls its own slot from the OAM pool, no flicker multiplexing needed */
/* While all weapons flew the same path, two projectiles were enough. With
   a separate path per weapon, several mounted weapons would otherwise
   share two places and swallow each other's shots. 6 is harmless against
   the 48-slot OAM pool, especially since they flicker and hold a slot only
   half the time. Original: the drone alone holds 80. */
/* 4 instead of 6, so the same as the main gun (MAX_BULLETS). User report
   31.07.: "there are more rear shots than front shots". They are also
   SLOWER - lvl_weapon_bullet_dy[0] is +48 (3 px per frame downwards) while
   the main gun does 8 px per frame - and therefore take almost three times
   as long to cross the screen. The larger pool accordingly left more of
   them standing at once. Measured cost: -2.5 % of frame time. */
#define MAX_WPBULLETS 4
/* Enemy firing behaviour. lvl_spawn_fire_rate[] is set for 35 of the 140
   spawns, so this is a real feature, not a stub. Its own small pool,
   separate from player, weapon and map object shots (the original has only
   a few towers with an active fire rate per level). */
/* A bursting wall crawler fires LVL_WCRAWL_SHOTS (3) balls AT ONCE; with
   four places a single burst would have emptied the pool for every other
   enemy. This costs no extra OAM: enemy shots share their slots via
   FLICKER_VIS (ebullets_draw), so they are never all visible at the same
   time. */
#define MAX_ENEMY_BULLETS 8u
#define ENEMY_SHOT_SPEED_FIX 32   /* 30 fps cap: 16 -> 32 (2 px per frame, same px/s as at 60 fps) */
#define MAX_PICKUPS  12   /* 12 for the boss cash rain. The original throws 18 tokens (9x50 + 9x100 credits); 18 x 2 OAM slots would be 36 of 48 - possible only because the death routine clears the enemy ring first, but too tight. 12 tokens = 6x50 + 6x100 = 900 credits, a deliberate deviation. Each active pickup takes at most 2 OAM slots from the pool. */
#define MAX_METAENEMIES 8   /* lvl_spawn_count[4] is now 8 rather than 4 */
#define MAX_WORMS 1u          /* lvl_spawn_count[5] = 1 */
#define MAX_WORM_SEGS 6u      /* >= max(lvl_spawn_worm_segs); bounds-checked on spawn */
/* Was 2, because the metasprites of the time all had exactly 2 cells. The
   map now brings metasprites with 4 cells (2x2 blocks). Both loops
   (metaenemy_spawn's OAM assignment and the drawing loop in draw_sprites)
   run to META_CELLS - with 2 only the UPPER two cells were drawn and the
   bottom row was missing entirely. No memory overrun (the loops are
   bounded by META_CELLS, not by lvl_meta_count), but half an enemy.
   Value = max(lvl_meta_count) EXCLUDING the ship metasprites 0-4, which
   have 7    cells but are drawn through SHIP_CELLS/ship_draw rather than
   as TMetaEnemy.    REMEMBER: check lvl_meta_count[] on every map update. */
#define META_CELLS 4
/* Simulated against the 121 paths / 140 spawns of the current export. The
   paths leave the screen for more than 80 frames at a stretch and come
   back; the earlier value of 80 killed them inside that gap. Sweep WITH
   pool pressure, visible enemy frames across the whole level: 80 -> 31273,
   120 -> 31666, 150 -> 31796, 200 -> 31796, 250 -> 31911, 300 -> 31911.
   Monotonic, plateau from 250. Two independent simulations agree that 250
   over 150 rescues exactly the last 115 frames of one remaining spawn. No
   measurable price: spawned chain links and pool peak are identical at
   every value, and nothing is left hanging at the end of the level. */
/* DURATION -> at 20 fps FPS_DUR brings this to 167 frames. This matters
   for the sprite streaming section boundaries: the grace counts in FRAMES,
   the lead in ROWS. 250 f x 0.333 px = 83 px and 167 f x 0.5 px = 83 px -
   the same distance, so the reserve is preserved. That is exactly why this
   is scaled rather than left alone. */
#define ENEMY_OFFSCREEN_GRACE 250u  /* frames of grace off screen before the slot is released */
/* The worm needs its own, larger grace: it deliberately spawns already
   invisible (spawn_y=149, behind the HUD bar, "still in its hole") and
   takes 129-147 frames before it is visible for the FIRST time. That is
   not a later re-entry like a normal enemy path - ENEMY_OFFSCREEN_GRACE
   only covers enemies already seen - but the initial hiding phase itself.
   At a grace of 80 all eight segments died long before they were ever on
   screen. */
#define WORM_OFFSCREEN_GRACE 170u

