// --- Helper functions --
static u8 collide(u8 ax, u8 ay, u8 bx, u8 by, u8 r) {
    u8 dx = (ax > bx) ? (u8)(ax - bx) : (u8)(bx - ax);
    u8 dy = (ay > by) ? (u8)(ay - by) : (u8)(by - ay);
    return (u8)(dx < r && dy < r);
}

/* ============ Hit zones ============    lvl_hitzone_* defines PRECISE,
   usually smaller hit areas per sprite reference    (same spr encoding as
   lvl_spawn_spr: 0x1000|meta for the ship per tilt stage,    0xC000|n /
   0x8000|n for enemy sprite strips). Before this, ship and enemy hits
   went exclusively through the generic point+radius collide() above.
   All 17 current entries have count=1 (a single rectangle), so this
   deliberately    handles ONE rectangle per reference rather than the
   multi-rectangle loop the    integration notes allow for. If a future
   export delivers count>1, only the    first rectangle is used - fix it
   then. */
/* Resolve only the RELATIVE hit zone (dx/dy/w/h, without an origin
   position). The 17-entry search lives here so it can be called ONCE at
   spawn and cached (see TEnemy.hz_dx / hit_test_cached) instead of running
   on every collision test. spr=0 (projectiles) is guaranteed not to match,
   since all 17 entries have bit 12/13/15 set - direct fallback without
   searching. */
static void hitzone_resolve(u16 spr, u8 fallback_w, u8 fallback_h,
                             s16 *dx, s16 *dy, u8 *w, u8 *h) {
    u8 i;
    if (spr != 0u) {
        for (i = 0u; i < (u8)LVL_HITZONE_COUNT; i++) {
            if (lvl_hitzone_spr[i] == spr) {
                u16 off = lvl_hitzone_off[i];
                *dx = lvl_hitzone_dx[off];
                *dy = lvl_hitzone_dy[off];
                *w  = lvl_hitzone_w[off];
                *h  = lvl_hitzone_h[off];
                return;
            }
        }
    }
    /* No hit zone defined -> the full sprite or metasprite area as a
       fallback. */
    *dx = 0; *dy = 0;
    *w = fallback_w; *h = fallback_h;
}

/* aw/ah/bw/bh as u16 for the same reason as the SetSprite parameters:
   a u8 parameter is zero-extended twice per call, and check_collisions()
   makes up to MAX_ENEMIES+MAX_METAENEMIES of them every frame. The values
   are widths, always positive, so nothing changes about the arithmetic. */
static u8 rects_overlap(s16 ax, s16 ay, u16 aw, u16 ah, s16 bx, s16 by, u16 bw, u16 bh) {
    if ((s16)(ax + (s16)aw) <= bx || (s16)(bx + (s16)bw) <= ax) return 0u;
    if ((s16)(ay + (s16)ah) <= by || (s16)(by + (s16)bh) <= ay) return 0u;
    return 1u;
}

/* BOTH sides already resolved: check_collisions() tests the ship against
   up to MAX_ENEMIES+MAX_METAENEMIES enemies per frame, and the ship hit
   zone depends only on the tilt stage, never changing within a single
   check_collisions() call. Resolve it once beforehand (hitzone_rect) and
   only compare rectangles here, instead of searching again for EVERY
   enemy. */
/* Does the comparison ITSELF rather than forwarding to rects_overlap().
   This is the innermost function of the frame - every shot against every
   enemy, every worm segment, every wall crawler. Forwarding cost a second
   far call with eight more arguments pushed on top of the ten this one
   already receives, for four comparisons of work. With cart_wait=3 every
   byte of that argument shuffling is paid for. Semantics unchanged, the
   comparisons are copied verbatim from rects_overlap().
   The x pair is tested FIRST: shots and enemies are pre-filtered in y by
   the caller (BULLET_YFILTER), so x is what actually separates them and
   the early return hits more often. */
static u8 rects_overlap_cached(s16 arx, s16 ary, u8 arw, u8 arh,
                                u8 bx, u8 by, s16 bdx, s16 bdy, u8 bw, u8 bh) {
    s16 rx = (s16)((s16)bx + bdx);
    s16 ry;
    if ((s16)(arx + (s16)arw) <= rx || (s16)(rx + (s16)bw) <= arx) return 0u;
    ry = (s16)((s16)by + bdy);
    if ((s16)(ary + (s16)arh) <= ry || (s16)(ry + (s16)bh) <= ary) return 0u;
    return 1u;
}

/* Ship fallback area 24x24. ship_hitzone_rect() /
   ship_hitzone_cache_init() are defined further down, because they need
   tilt_by_level which is only declared there. */
#define PICKUP_GRAB_R 18u   /* collection radius, centre to centre, see pickups_update */
/* Only in effect while the tool supplies NO hit zone for the ship
   metasprites (see ship_hitzone_cache_init). Pulled along with the ship,
   and narrow on purpose - see the probe points. */
#define SHIP_HIT_FALLBACK_W 8u
#define SHIP_HIT_FALLBACK_H 16u
/* Generic fallback for enemies without a matching hit zone: one strip tile
   (8x8). */
#define ENEMY_HIT_FALLBACK_W 8u
#define ENEMY_HIT_FALLBACK_H 8u
/* Projectiles (shots and weapon shots) have no hit zone entries of their
   own - they are treated as a small fixed box (tile size), while the other
   side stays precise. */
#define BULLET_HIT_W 8u
#define BULLET_HIT_H 8u
/* Sweep test (anti-tunnelling for TEST_COLL_HALF): between two collision
   checks a main gun shot travels 16 px. The shot box is therefore extended
   DOWNWARDS by the distance covered during the halved checks - the shot
   flies up, so the path lies below the current position - and a narrow
   target between two sample points is still hit. Hardware: block 4 halved
   = 95-107 -> 83-105 VBC. */
#if TEST_COLL_HALF
#define BULLET_SWEEP 16u
#else
#define BULLET_SWEEP 0u
#endif
/* Y distance prefilter: if an enemy is vertically further away than this,
   its hit zone cannot possibly intersect the shot box.    STAYS AT 48,
   even with the box extended by BULLET_SWEEP. Raising it to 64 was    a
   mistake - the extension only works DOWNWARDS, while the UPPER filter
   bound    depends solely on the enemy hit zone. Checked against the real
   data    (lvl_hitzone_dy/h): the largest dy+h is 21 and the lowest bound
   dy-24 is -24,    so 48 has more than double the margin on both sides.
   And 64 was EXPENSIVE: it    let noticeably more pairs into the rectangle
   test, 90 -> 88 on hardware. */
#define BULLET_YFILTER 48

/* SCR2 terrain: logical palettes 0-11 map to hardware slots 0,5,6-15. The
   bar occupies slots 1-4; slot 5 (formerly the digits) is free since the
   digits became sprites and is used for terrain as well - the map needs 12
   palettes. MORE than 12 do not fit (16 hardware slots minus 4 for the
   bar); if a future export delivers more, the size check in build_lvl1()
   complains. */
static const u8 scr2_pal_hw[12] = { 0u, 5u, 6u, 7u, 8u, 9u, 10u, 11u, 12u, 13u, 14u, 15u };
#define SCR2_PAL_N (sizeof(lvl_pal_scr2) / sizeof(lvl_pal_scr2[0]))
#define SCR1_PAL_N (sizeof(lvl_pal_scr1) / sizeof(lvl_pal_scr1[0]))
/* ===== Substitute mapping for unmappable SCR2 palettes =====    The map
   may use up to 16 logical SCR2 palettes but only the first 12 can be
   mapped (the HUD bar holds hardware slots 1-4). Every drawing site used
   to fall    back SILENTLY to palette 0, which is grey/blue - visible as
   "shot flowers grey    instead of brown" and "one frame of the worm hole
   animation grey".    Instead of 0 the CLOSEST usable palette by colour is
   chosen now. That does not    replace the export - it is only right once
   the tool re-exports against the    12-palette budget - but it looks like
   "slightly different colour" rather than    "broken".    g_digit_pal_hw
   solves the same problem for the digits on the HUD bar: they are
   sprite strip tiles but are drawn as BACKGROUND and therefore need an
   SCR2    palette with the same colours. That used to be a hard-wired slot
   which in one    export contained a brown, giving "brown streaks in the
   digits". The matching    palette is now SEARCHED FOR once rather than
   guessed. */
static u8 g_scr2_pal_map[16];   /* logical map palette -> hardware slot, including substitutes */
static u8 g_digit_pal_hw = 6u;  /* hardware slot for the bar digits (initial value = the old fixed one) */

static u16 pal_dist(const u16 *a, const u16 *b) {
    /* Sum of squared channel distances over colours 1..3 (0 is always
       transparent/background). 12-bit 0BGR, 4 bits per channel. */
    u16 sum = 0u;
    u8 k;
    for (k = 1u; k < 4u; k++) {
        u8 ar = (u8)(a[k] & 0xFu),        br = (u8)(b[k] & 0xFu);
        u8 ag = (u8)((a[k] >> 4) & 0xFu), bg = (u8)((b[k] >> 4) & 0xFu);
        u8 ab = (u8)((a[k] >> 8) & 0xFu), bb = (u8)((b[k] >> 8) & 0xFu);
        s8 dr = (s8)(ar - br), dg = (s8)(ag - bg), db = (s8)(ab - bb);
        sum = (u16)(sum + (u16)((s16)dr * dr) + (u16)((s16)dg * dg) + (u16)((s16)db * db));
    }
    return sum;
}

static void scr2_pal_map_init(void) {
    u8 p, q, usable = (u8)sizeof(scr2_pal_hw);
    if (usable > (u8)SCR2_PAL_N) usable = (u8)SCR2_PAL_N;
    for (p = 0u; p < 16u; p++) {
        if (p < usable) { g_scr2_pal_map[p] = scr2_pal_hw[p]; continue; }
        if (p >= (u8)SCR2_PAL_N) { g_scr2_pal_map[p] = scr2_pal_hw[0]; continue; }
        { u8 best = 0u; u16 bd = 0xFFFFu;
          for (q = 0u; q < usable; q++) {
              u16 d = pal_dist(lvl_pal_scr2[p], lvl_pal_scr2[q]);
              if (d < bd) { bd = d; best = q; }
          }
          g_scr2_pal_map[p] = scr2_pal_hw[best]; }
    }
    /* Digits: find the SCR2 palette closest to the digits' sprite palette.
       With the current export this is an EXACT match; the old hard-wired
       slot was not. */
    { u8 dpal = lvl_sspr_a_pal[(u16)(SPR_S_DIGIT0 - 1u)];
      u8 best = 2u; u16 bd = 0xFFFFu;
      if (dpal < (u8)(sizeof(lvl_pal_sprites) / sizeof(lvl_pal_sprites[0]))) {
          for (q = 0u; q < usable; q++) {
              u16 d = pal_dist(lvl_pal_sprites[dpal], lvl_pal_scr2[q]);
              if (d < bd) { bd = d; best = q; }
          }
      }
      g_digit_pal_hw = scr2_pal_hw[best]; }
}
/* Boss body hit-flash targets (see the boss block and scr_pal_load). SCR2
   is fully occupied, so the body a cells are switched to the EXISTING
   bright bar palette 4 ("salmon") - a colour shift, its colours stay as
   they are and the bar is untouched. SCR1 slot 14 is free, so a real white
   flash palette lives there for the b plane. */
#define BOSS_FLASH_SCR2_PAL 4u
#define BOSS_FLASH_SCR1_PAL 14u
/* these now sit further up, next to scr2_pal_hw - scr2_pal_map_init()
   needs SCR2_PAL_N and is defined before this point. */

/* ============ Compact custom font (instead of the full BIOS system font)
   ============    SysSetSystemFont() fills ALL 96 ASCII tiles into slots
   32-127, because    PrintString() addresses character tiles DIRECTLY by
   ASCII code without a    lookup. Text here only needs 37 characters (A-Z,
   0-9, space). So the 37 needed    glyphs are copied once from their BIOS
   positions into a compact zone (slots    32-68), after which slots 69-127
   count as free for terrain.    PrintStringCustom() replaces PrintString()
   everywhere and uses    font_tile_for_char() as a lookup instead of raw
   ASCII addressing. */
/* The compact 8x8 font has been REMOVED WITHOUT REPLACEMENT. It was only
   used for "GAME OVER" and "PRESS A" and permanently held VRAM tiles in an
   address space that is allocated down to the last tile. The game over
   screen now writes its text in the 16x16 intro alphabet on a black
   background, where VRAM is free anyway because neither terrain nor
   sprites are visible. Gone with it: FONT_BASE / FONT_CHAR_COUNT,
   font_charset, font_compact_init(), font_tile_for_char(),
   PrintStringCustom() and the SysSetSystemFont() call in main().    IF 8x8
   TEXT IS EVER NEEDED AGAIN: use the shop font (lvl_shop_font_*, in ROM
   and loaded for the shop anyway) or the intro alphabet - NOT the BIOS
   font,    which is no longer in VRAM now that SysSetSystemFont() is gone. */

// --- Install level 1 terrain VRAM --
/* start_idx: the first SHARED_PREFIX_COUNT entries of lvl_tile_used_A/B
   are deliberately IDENTICAL and therefore sit on the same physical VRAM
   slots in every segment (g_lvl_vram[j] is segment independent), so a
   switch does not have to re-upload that shared block, only the segment-
   specific rest. The initial build (empty VRAM) still needs start_idx=0,
   see the caller. */
static void build_lvl1(u16 start_idx) {
    volatile u16 *p;
    volatile u16 *dst;
    const u16 *src;
    u16 w, j;
    u8 i, slot;

    scr2_pal_map_init();   /* determine the substitute mapping and the digit palette */
    /* SCR2 terrain palettes: lvl_pal_scr2 mapped to hardware slots per
       scr2_pal_hw. Size check: if an export delivers more palettes than
       the table has slots, the surplus is NOT loaded - the tiles then look
       visibly wrong during testing rather than silently overwriting some
       slot. */
    p = SCROLL_2_PALETTE;
    for (i = 0u; i < (u8)SCR2_PAL_N && i < (u8)sizeof(scr2_pal_hw); i++) {
        slot = scr2_pal_hw[i];
        p[(u16)slot * 4u + 0u] = 0x0000u;
        p[(u16)slot * 4u + 1u] = lvl_pal_scr2[i][1];
        p[(u16)slot * 4u + 2u] = lvl_pal_scr2[i][2];
        p[(u16)slot * 4u + 3u] = lvl_pal_scr2[i][3];
    }
    /* SCR1 terrain palettes: slots 0..N-1 directly (the export currently
       delivers 5; slot 15 stays reserved for STAR_PAL) */
    p = SCROLL_1_PALETTE;
    for (i = 0u; i < (u8)SCR1_PAL_N; i++) {
        p[(u16)i * 4u + 0u] = 0x0000u;
        p[(u16)i * 4u + 1u] = lvl_pal_scr1[i][1];
        p[(u16)i * 4u + 2u] = lvl_pal_scr1[i][2];
        p[(u16)i * 4u + 3u] = lvl_pal_scr1[i][3];
    }
    /* Boss body hit flash. SCR2 is fully occupied (terrain 0,5..15 plus
       bar 1..4) - there is NO free SCR2 slot for a white palette of its
       own, and a first attempt at overwriting slot 4 with white turned bar
       cells white. Solution: the body flash SWITCHES the body cells to an
       EXISTING high-contrast SCR2 palette (slot 4, "salmon", bright). Its
       colours stay unchanged, so the bar is untouched; only the palette
       number of the body cells changes, which is the flash. For the SCR1 b
       plane, slot 14 is free in the export, so a real WHITE flash palette
       goes there. */
    { volatile u16 *ps1 = SCROLL_1_PALETTE;
      ps1[(u16)BOSS_FLASH_SCR1_PAL * 4u + 1u] = 0x0FFFu;
      ps1[(u16)BOSS_FLASH_SCR1_PAL * 4u + 2u] = 0x0FFFu;
      ps1[(u16)BOSS_FLASH_SCR1_PAL * 4u + 3u] = 0x0FFFu; }
    /* Tile data (compacted): copy only the tiles of the ACTIVE segment
       (lvl1_select_segment() called beforehand) into VRAM, with target
       slots via the g_lvl_vram indirection. */
    for (j = start_idx; j < g_lvl_tile_used_count; j++) {
        dst = (volatile u16*)0xA000u + (u16)g_lvl_vram[j] * 8u;
        src = &lvl_tile_data[g_lvl_tile_used[j]][0];
        for (w = 0u; w < 8u; w++) dst[w] = src[w];
    }
}

